/**
 * Raises the Gradle daemon's heap and metaspace, and bounds everything it forks.
 *
 * Expo's template ships `-Xmx2048m -XX:MaxMetaspaceSize=512m`. That is not enough for a release
 * build of this project: R8, the Kotlin compiler and the native (CMake/NDK) toolchains all load
 * large numbers of classes into the same daemon, and the release run fails with
 * `java.lang.OutOfMemoryError: Metaspace` partway through.
 *
 * This lives as a config plugin rather than an edit to `android/gradle.properties`, because that
 * file is regenerated by every `expo prebuild` and a hand edit would silently disappear.
 */
const { withGradleProperties } = require('@expo/config-plugins');

const PROPERTIES = {
  'org.gradle.jvmargs': '-Xmx4096m -XX:MaxMetaspaceSize=1536m -XX:+HeapDumpOnOutOfMemoryError',
  // A worker daemon that cannot get memory does not fail gracefully: it dies while starting and
  // the build stops with "Unable to connect to the child process ... hit a timeout after 120s".
  // On a 16 GB machine running an emulator and Metro beside the build, Gradle's default worker
  // count is enough to provoke that, so the worker count and the Kotlin daemon are both bounded.
  'org.gradle.workers.max': '2',
  'kotlin.daemon.jvmargs': '-Xmx1536m -XX:MaxMetaspaceSize=512m',
};

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (mod) => {
    for (const [key, value] of Object.entries(PROPERTIES)) {
      const existing = mod.modResults.find(
        (item) => item.type === 'property' && item.key === key,
      );
      if (existing && existing.type === 'property') existing.value = value;
      else mod.modResults.push({ type: 'property', key, value });
    }
    return mod;
  });
};
